    Bug 2067655 - Fix a regression preventing PDF attachments from opening in the internal viewer. r=darktrojan

    Differential Revision: https://phabricator.services.mozilla.com/D322298

diff --git a/mail/modules/AttachmentInfo.sys.mjs b/mail/modules/AttachmentInfo.sys.mjs
index 4d21bcf861b..8dd0783a57e 100644
--- a/mail/modules/AttachmentInfo.sys.mjs
+++ b/mail/modules/AttachmentInfo.sys.mjs
@@ -417,7 +417,7 @@ export class AttachmentInfo {
         // Add the content type to avoid a "how do you want to open this?"
         // dialog. The type may already be there, but that doesn't matter.
         let url = this.url;
-        if (!url.includes("type=")) {
+        if (!url.includes("type=application/pdf")) {
           url += url.includes("?") ? "&" : "?";
           url += "type=application/pdf";
         }
